    'con.and': ['{a} en {b}', '{a} und {b}', '{a} and {b}'],
    'con.account': ['{b}-account', '{b}-Konto', '{b} account'],
    'con.q': ['<strong>Diafragmo</strong> wil toegang tot je e-mail én agenda:', '<strong>Diafragmo</strong> möchte auf deine E-Mails und deinen Kalender zugreifen:', '<strong>Diafragmo</strong> would like access to your email and calendar:'],
    'con.p1': ['E-mail verzenden namens jou', 'E-Mails in deinem Namen senden', 'Send email on your behalf'],
    'con.p1s': ['Offertes, facturen en herinneringen gaan vanaf {a} en staan ook in je eigen map Verzonden.', 'Angebote, Rechnungen und Erinnerungen gehen von {a} raus und landen auch in deinem Ordner „Gesendet“.', 'Quotes, invoices and reminders are sent from {a} and also appear in your own Sent folder.'],
    'con.p2': ['Berichten met klanten lezen die bij projecten horen', 'Nachrichten mit Kunden lesen, die zu Projekten gehören', 'Read messages with clients that belong to projects'],
    'con.p2s': ['Alleen mail van en naar adressen van je klanten. Je overige mail blijft privé.', 'Nur Mails von und an Adressen deiner Kunden. Deine übrigen Mails bleiben privat.', 'Only email to and from your clients’ addresses. The rest of your email stays private.'],
    'con.p3': ['Agenda lezen om beschikbaarheid te checken', 'Kalender lesen, um Verfügbarkeit zu prüfen', 'Read your calendar to check availability'],
    'con.p3s': ['Alleen vrij/bezet, zodat je bij het plannen dubbele boekingen ziet. De inhoud van je afspraken blijft privé.', 'Nur frei/belegt, damit du beim Planen Doppelbuchungen siehst. Der Inhalt deiner Termine bleibt privat.', 'Only free/busy, so you can spot double bookings while planning. The content of your appointments stays private.'],
    'con.p4': ['Opnamedagen en deadlines in je agenda zetten', 'Drehtage und Deadlines in deinen Kalender eintragen', 'Add shoot days and deadlines to your calendar'],
    'con.p4s': ['In een aparte agenda ‘Diafragmo’ in je {c}, met locatie en call time. Wijzigingen worden automatisch bijgewerkt.', 'In einem eigenen Kalender „Diafragmo“ in deinem {c}, mit Ort und Call Time. Änderungen werden automatisch übernommen.', 'In a separate ‘Diafragmo’ calendar in your {c}, with location and call time. Changes are updated automatically.'],
    'con.foot': ['Eén keer inloggen is genoeg: daarna werken e-mail en agenda allebei. In Instellingen zet je E-mail of Agenda los aan of uit, en je kunt de toegang altijd intrekken in Diafragmo of in je {b}-account. Demo: er wordt niet echt ingelogd.', 'Einmal anmelden reicht: Danach funktionieren E-Mail und Kalender. In den Einstellungen schaltest du E-Mail oder Kalender einzeln an oder aus, und du kannst den Zugriff jederzeit in Diafragmo oder in deinem {b}-Konto widerrufen. Demo: Es findet keine echte Anmeldung statt.', 'Signing in once is enough: after that, email and calendar both work. In Settings you can switch Email or Calendar on or off separately, and you can revoke access at any time in Diafragmo or in your {b} account. Demo: no real sign-in takes place.'],
    'con.allow': ['Toestaan', 'Zulassen', 'Allow'],
    'con.connecting': ['Verbinden met {p}…', 'Verbinde mit {p} …', 'Connecting to {p}…'],
    'con.done': ['{p} gekoppeld (demo): e-mail via {a} · {n} opnamedagen en deadlines in je {c}', '{p} verbunden (Demo): E-Mail über {a} · {n} Drehtage und Deadlines in deinem {c}', '{p} connected (demo): email via {a} · {n} shoot days and deadlines in your {c}'],
