    'kop.bccSub': ['Ontvang een kopie van elke verstuurde mail', 'Erhalte eine Kopie jeder gesendeten Mail', 'Receive a copy of every email sent'],
    'kop.auto': ['Automatisch koppelen aan projecten', 'Automatisch Projekten zuordnen', 'Link to projects automatically'],
    'kop.autoSub': ['Op basis van het e-mailadres van de klant', 'Anhand der E-Mail-Adresse des Kunden', 'Based on the client’s email address'],
