    'kop.check': ['Beschikbaarheid checken bij plannen', 'Verfügbarkeit beim Planen prüfen', 'Check availability while planning'],
    'kop.checkSub': ['Toont “vrij / bezet” bij het kiezen van een datum', 'Zeigt „frei / belegt“ bei der Datumsauswahl', 'Shows “free / busy” when picking a date'],
    'kop.calHintOn': ['Zet Agenda aan bij je gekoppelde account om deze opties te gebruiken.', 'Schalte Kalender bei deinem verbundenen Konto ein, um diese Optionen zu nutzen.', 'Turn on Calendar for your connected account to use these options.'],
    'kop.calHintConnect': ['Koppel eerst Microsoft 365 of Google om deze opties te gebruiken.', 'Verbinde zuerst Microsoft 365 oder Google, um diese Optionen zu nutzen.', 'Connect Microsoft 365 or Google first to use these options.'],
